/**
 * Infer category from search terms using keyword-to-category mapping.
 * If 2+ terms map to the same parent category, returns high confidence.
 * If only 1 term matches, returns low confidence.
 * Returns none if no consensus.
 */
export function inferCategoryFromTerms(terms: string[]): InferenceResult {
  if (terms.length === 0) return { categoryId: null, parentCategoryId: null, parentSlug: null, confidence: "none" }

  // Count how many terms point to each parent category
  const parentVotes: Record<string, { count: number; parentId: string; parentSlug: string; subcategoryIds: string[] }> = {}

  for (const term of terms) {
    const lower = term.toLowerCase().trim()
    const matches = KEYWORD_MAP[lower]
    if (!matches) continue

    // Track which parents this term votes for (deduplicate per term)
    const votedParents = new Set<string>()
    for (const match of matches) {
      if (votedParents.has(match.parentSlug)) continue
      votedParents.add(match.parentSlug)

      if (!parentVotes[match.parentSlug]) {
        parentVotes[match.parentSlug] = { count: 0, parentId: match.parentId, parentSlug: match.parentSlug, subcategoryIds: [] }
      }
      parentVotes[match.parentSlug].count++
      if (!parentVotes[match.parentSlug].subcategoryIds.includes(match.subcategoryId)) {
        parentVotes[match.parentSlug].subcategoryIds.push(match.subcategoryId)
      }
    }
  }

  // Find the parent with the most votes
  const entries = Object.values(parentVotes)
  if (entries.length === 0) return { categoryId: null, parentCategoryId: null, parentSlug: null, confidence: "none" }

  entries.sort((a, b) => b.count - a.count)
  const best = entries[0]

  // High confidence: 2+ terms agree on same parent
  if (best.count >= 2) {
    // If there's a specific subcategory, use it; otherwise use parent
    const categoryId = best.subcategoryIds.length === 1 ? best.subcategoryIds[0] : best.parentId
    return { categoryId, parentCategoryId: best.parentId, parentSlug: best.parentSlug, confidence: "high" }
  }

  // Low confidence: only 1 term matches
  const categoryId = best.subcategoryIds.length === 1 ? best.subcategoryIds[0] : best.parentId
  return { categoryId, parentCategoryId: best.parentId, parentSlug: best.parentSlug, confidence: "low" }
}